def test_overwrite_splits():
    assert paint([(0, 10, 'red'), (3, 5, 'blue')]) == [(0, 3, 'red'), (3, 5, 'blue'), (5, 10, 'red')]

def test_touching_same_color_merges_but_gap_does_not():
    assert paint([(0, 3, 'red'), (3, 6, 'red'), (7, 9, 'red')]) == [(0, 6, 'red'), (7, 9, 'red')]

def test_overwrite_can_create_merge():
    assert paint([(0, 4, 'red'), (4, 8, 'blue'), (4, 8, 'red')]) == [(0, 8, 'red')]

def test_empty_and_reversed_ranges():
    assert paint([(5, 5, 'red'), (9, 6, 'blue'), (1, 2, 'g')]) == [(1, 2, 'g'), (6, 9, 'blue')]
    assert paint([]) == []

def test_erase():
    assert paint([(0, 10, 'red'), (2, 4, None), (12, 8, None)]) == [(0, 2, 'red'), (4, 8, 'red')]

def test_erase_then_repaint_merges():
    assert paint([(0, 6, 'red'), (2, 4, None), (2, 4, 'red')]) == [(0, 6, 'red')]

def test_underpaint_only_fills_blank():
    assert paint([(2, 4, 'red'), (0, 10, '^blue')]) == [(0, 2, 'blue'), (2, 4, 'red'), (4, 10, 'blue')]

def test_underpaint_merges_with_neighbour():
    assert paint([(0, 3, 'red'), (5, 8, 'blue'), (8, 0, '^red')]) == [(0, 5, 'red'), (5, 8, 'blue')]

def test_underpaint_after_erase_then_overwrite():
    ops = [(0, 10, 'red'), (3, 6, None), (0, 10, '^green'), (5, 7, 'red')]
    assert paint(ops) == [(0, 3, 'red'), (3, 5, 'green'), (5, 10, 'red')]

def test_negative_coordinates():
    assert paint([(-5, -1, 'x'), (-1, -1, 'y'), (-3, -2, None)]) == [(-5, -3, 'x'), (-2, -1, 'x')]

