    for s, e, c in ops:
        if s > e:
            s, e = e, s
        if s < e:
            norm.append((s, e, c))
    pts = sorted({p for s, e, _ in norm for p in (s, e)})
    out = []
    for a, b in zip(pts, pts[1:]):
        color = None
        for s, e, c in norm:
            if s <= a and b <= e:
                if c is None:
                    color = None
                elif c.startswith("^"):
                    if color is None:
                        color = c[1:]
                else:
                    color = c
        if color is None:
            continue
        if out and out[-1][1] == a and out[-1][2] == color:
            out[-1] = (out[-1][0], b, color)
        else:
            out.append((a, b, color))
    return out

