def test_implicit_tasks_and_duplicate_deps():
    deps = {'app': ['lib', 'lib', 'cfg'], 'lib': ['cfg']}
    assert build_order(deps) == (['cfg', 'lib', 'app'], [])

def test_priority_only_among_ready_tasks():
    deps = {'a': [], 'b': [], 'c': ['a']}
    assert build_order(deps, {'b': 2, 'c': 5}) == (['b', 'a', 'c'], [])

def test_missing_and_negative_priority():
    assert build_order({'x': [], 'y': [], 'z': []}, {'x': -1}) == (['y', 'z', 'x'], [])
    assert build_order({'b': [], 'a': []}, None) == (['a', 'b'], [])

