import heapq


def build_order(deps, priority=None):
    priority = priority or {}
    nodes = set(deps)
    for reqs in deps.values():
        nodes.update(reqs)
    waiting = {n: set() for n in nodes}
    users = {n: set() for n in nodes}
    for task, reqs in deps.items():
        for r in reqs:
            waiting[task].add(r)
            users[r].add(task)
    left = {n: len(waiting[n]) for n in nodes}
    heap = [(-priority.get(n, 0), n) for n in nodes if left[n] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, n = heapq.heappop(heap)
        order.append(n)
        for u in users[n]:
            left[u] -= 1
            if left[u] == 0:
                heapq.heappush(heap, (-priority.get(u, 0), u))
    placed = set(order)
    stuck = sorted(n for n in nodes if n not in placed)
    return order, stuck

