def leaderboard(results):
    totals = {}
    banned = set()
    for player, pts, secs in results:
        if pts < 0:
            banned.add(player)
        p, s = totals.get(player, (0, 0))
        totals[player] = (p + pts, s + secs)
    rows = sorted((-p, s, name) for name, (p, s) in totals.items() if name not in banned)
    out = []
    for i, (neg_p, s, name) in enumerate(rows):
        if i > 0 and (rows[i - 1][0], rows[i - 1][1]) == (neg_p, s):
            rank = out[-1][0]
        else:
            rank = i + 1
        out.append((rank, name, -neg_p, s))
    return out

