    jobs = [('a', 0, 4, 0), ('b', 0, 1, 0), ('z', 4, 1, 9)]
    assert run_jobs(jobs) == [('a', 0, 4), ('z', 4, 5), ('b', 5, 6)]

def test_tiebreak_arrival_then_name():
    jobs = [('m', 2, 1, 3), ('k', 1, 1, 3), ('j', 1, 1, 3), ('x', 0, 5, 0)]
    assert run_jobs(jobs) == [('x', 0, 5), ('j', 5, 6), ('k', 6, 7), ('m', 7, 8)]

