    jobs = [('blocker', 0, 4, 9), ('old', 0, 1, 1), ('new', 4, 1, 2)]
    assert run_jobs(jobs) == [('blocker', 0, 4), ('new', 4, 5), ('old', 5, 6)]

def test_aging_tie_falls_back_to_arrival():
    jobs = [('blocker', 0, 9, 9), ('old', 0, 1, 1), ('new', 9, 1, 2)]
    assert run_jobs(jobs) == [('blocker', 0, 9), ('old', 9, 10), ('new', 10, 11)]

def test_aging_measured_from_arrival_across_several_picks():
    jobs = [('a', 0, 4, 9), ('b', 0, 4, 9), ('c', 0, 4, 9), ('w', 0, 1, 1), ('n', 12, 1, 2)]
    assert run_jobs(jobs) == [('a', 0, 4), ('b', 4, 8), ('c', 8, 12), ('w', 12, 13), ('n', 13, 14)]

def test_empty():
    assert run_jobs([]) == []

