def reachable(grid, start, max_climb=1, max_drop=None):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def height(ch):
        return 0 if ch == "=" else int(ch)

    seen = {tuple(start)}
    stack = [tuple(start)]
    while stack:
        r, c = stack.pop()
        h = height(grid[r][c])
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            ch = grid[nr][nc]
            if ch == "#":
                continue
            nh = height(ch)
            if nh - h > max_climb:
                continue
            if max_drop is not None and h - nh > max_drop:
                continue
            if ch == "=":
                while True:
                    tr, tc = nr + dr, nc + dc
                    if 0 <= tr < rows and 0 <= tc < cols and grid[tr][tc] == "=":
                        nr, nc = tr, tc
                    else:
                        break
            if (nr, nc) not in seen:
                seen.add((nr, nc))
                stack.append((nr, nc))
    return len(seen)

