def window_sums(events, window, max_gap):
    by_t = {}
    for t, v in events:
        by_t[t] = by_t.get(t, 0) + v
    ts = sorted(by_t)
    out = []
    seg_start = None
    prev = None
    for t in ts:
        if prev is None or t - prev > max_gap:
            seg_start = t
        prev = t
        total = sum(by_t[s] for s in ts if seg_start <= s <= t and s > t - window)
        out.append((t, total))
    return out

