def pack(items, capacity):
    norm = []
    for it in items:
        name, size = it[0], it[1]
        group = it[2] if len(it) > 2 else None
        if size > capacity:
            raise ValueError(f"{name} does not fit")
        norm.append((name, size, group))
    norm.sort(key=lambda x: (-x[1], x[0]))
    bins = []
    for name, size, group in norm:
        best = None
        for i, b in enumerate(bins):
            if b[0] >= size and (group is None or group not in b[2]):
                if best is None or b[0] - size < bins[best][0] - size:
                    best = i
        if best is None:
            bins.append([capacity, [], set()])
            best = len(bins) - 1
        b = bins[best]
        b[0] -= size
        b[1].append(name)
        if group is not None:
            b[2].add(group)
    return [b[1] for b in bins]

