def overlay(ranges, min_count=1):
    norm = [(s, e, lab.lower()) for s, e, lab in ranges]
    pts = sorted({p for s, e, _ in norm for p in (s, e + 1)})
    out = []
    for a, b in zip(pts, pts[1:]):
        covering = [lab for s, e, lab in norm if s <= a and b - 1 <= e]
        if not covering or len(covering) < min_count:
            continue
        labels = tuple(sorted(set(covering)))
        if out and out[-1][1] == a - 1 and out[-1][2] == labels:
            out[-1] = (out[-1][0], b - 1, labels)
        else:
            out.append((a, b - 1, labels))
    return out

