    assert round_robin([('A', 0, 5), ('B', 1, 3), ('C', 2, 1)], 2, 0) == {'A': 9, 'B': 8, 'C': 5}

def test_arrival_at_slice_end_goes_before_preempted():
    assert round_robin([('A', 0, 4), ('B', 2, 1)], 2, 0) == {'A': 5, 'B': 3}

def test_idle_until_next_arrival_and_same_time_order():
    assert round_robin([('A', 0, 1), ('B', 5, 2)], 4, 0) == {'A': 1, 'B': 7}
    assert round_robin([('Z', 0, 1), ('Y', 0, 1)], 1, 0) == {'Z': 1, 'Y': 2}

def test_switch_cost_including_first_slice():
    assert round_robin([('A', 0, 3), ('B', 0, 2)], 2, 1) == {'A': 8, 'B': 6}

def test_no_switch_when_same_process_continues():
    assert round_robin([('A', 0, 5)], 2, 3) == {'A': 8}

def test_switch_after_idle():
    assert round_robin([('A', 0, 2), ('B', 10, 2)], 5, 1) == {'A': 3, 'B': 13}

def test_arrival_during_switch():
    assert round_robin([('A', 0, 2), ('B', 0, 3), ('C', 1, 1)], 2, 2) == {'A': 4, 'B': 14, 'C': 11}

def test_switch_with_arrival_at_slice_end():
    assert round_robin([('P', 0, 3), ('Q', 3, 2), ('R', 4, 1)], 2, 1) == {'P': 8, 'Q': 6, 'R': 10}

