from collections import deque


def round_robin(procs, quantum, switch):
    arrivals = deque(sorted(procs, key=lambda p: p[1]))
    remaining = {name: burst for name, _, burst in procs}
    queue = deque()
    done = {}
    t = 0
    last = None

    def admit(upto):
        while arrivals and arrivals[0][1] <= upto:
            queue.append(arrivals.popleft()[0])

    admit(t)
    while queue or arrivals:
        if not queue:
            t = max(t, arrivals[0][1])
            admit(t)
            continue
        name = queue.popleft()
        if name != last:
            t += switch
        run = min(quantum, remaining[name])
        t += run
        remaining[name] -= run
        last = name
        admit(t)
        if remaining[name]:
            queue.append(name)
        else:
            done[name] = t
    return done

