def assign_rooms(meetings, capacities):
    series = {}
    for mid, s, e, n in meetings:
        series.setdefault(mid, []).append((s, e, n))

    def first_key(mid):
        s, e = min((s, e) for s, e, _ in series[mid])
        return (s, e, mid)

    booked = [[] for _ in capacities]
    result = {}
    for mid in sorted(series, key=first_key):
        occ = series[mid]
        need = max(n for _, _, n in occ)
        best = None
        for i, cap in enumerate(capacities):
            if cap < need:
                continue
            free = all(not (s < be and bs < e) for s, e, _ in occ for bs, be in booked[i])
            if free and (best is None or cap < capacities[best]):
                best = i
        if best is None:
            result[mid] = None
        else:
            booked[best].extend((s, e) for s, e, _ in occ)
            result[mid] = best + 1
    return result

