def test_plain_streaks_with_duplicates():
    log = [('a', 3), ('a', 1), ('a', 2), ('a', 2), ('a', 7), ('b', 10)]
    assert longest_streaks(log, freezes=0) == {'a': (3, 1), 'b': (1, 10)}

def test_tie_reports_earliest():
    assert longest_streaks([('u', 5), ('u', 6), ('u', 1), ('u', 2)], freezes=0) == {'u': (2, 1)}

def test_single_freeze_default():
    assert longest_streaks([('a', 1), ('a', 2), ('a', 4), ('a', 5)]) == {'a': (4, 1)}
    assert longest_streaks([('a', 1), ('a', 2), ('a', 4), ('a', 6)]) == {'a': (3, 1)}
    assert longest_streaks([('a', 1), ('a', 2), ('a', 5)]) == {'a': (2, 1)}

def test_two_day_gap_breaks():
    assert longest_streaks([('a', d) for d in (1, 2, 5, 6, 7)]) == {'a': (3, 5)}

def test_window_must_slide_past_old_gap():
    assert longest_streaks([('a', d) for d in (1, 3, 4, 5, 7, 8, 9, 10)]) == {'a': (7, 3)}

def test_freezes_parameter():
    log = [('a', d) for d in (1, 2, 4, 5, 7, 8)]
    assert longest_streaks(log) == {'a': (4, 1)}
    assert longest_streaks(log, freezes=2) == {'a': (6, 1)}
    assert longest_streaks(log, freezes=0) == {'a': (2, 1)}

def test_multiple_users():
    log = [('x', 1), ('x', 1), ('x', 3), ('y', 2), ('y', 4), ('y', 6), ('y', 8)]
    assert longest_streaks(log) == {'x': (2, 1), 'y': (2, 2)}
    assert longest_streaks(log, freezes=3) == {'x': (2, 1), 'y': (4, 2)}
    assert longest_streaks([]) == {}

