def longest_streaks(log, freezes=1):
    days = {}
    for user, day in log:
        days.setdefault(user, set()).add(day)
    result = {}
    for user, ds in days.items():
        ds = sorted(ds)
        best = None
        i = 0
        gaps = 0
        for j in range(len(ds)):
            if j > 0:
                diff = ds[j] - ds[j - 1]
                if diff > 2:
                    i = j
                    gaps = 0
                elif diff == 2:
                    gaps += 1
                    while gaps > freezes:
                        if ds[i + 1] - ds[i] == 2:
                            gaps -= 1
                        i += 1
            length = j - i + 1
            if best is None or length > best[0]:
                best = (length, ds[i])
        result[user] = best
    return result

