    rows = [('x', 'p', 1), ('y', 'q', 2), ('y', 'r', 2), ('x', 's', 3)]
    assert top_per_group(rows, 5) == {'x': ['s', 'p'], 'y': ['q', 'r']}

def test_duplicate_names_use_highest_score():
    assert top_per_group([('g', 'a', 10), ('g', 'a', 9), ('g', 'b', 8)], 2) == {'g': ['a', 'b']}
    assert top_per_group([('g', 'a', 3), ('g', 'b', 4), ('g', 'a', 10)], 1) == {'g': ['a']}

