def top_per_group(rows, k):
    if k <= 0:
        return {}
    best = {}
    for group, name, score in rows:
        g = best.setdefault(group, {})
        if name not in g:
            g[name] = score
        elif score is not None and (g[name] is None or score > g[name]):
            g[name] = score
    out = {}
    for group, g in best.items():
        ranked = sorted(g.items(), key=lambda kv: (1, 0, kv[0]) if kv[1] is None else (0, -kv[1], kv[0]))
        kept = ranked[:k]
        cut = kept[-1][1]
        for name, score in ranked[k:]:
            if score == cut:
                kept.append((name, score))
            else:
                break
        out[group] = [name for name, _ in kept]
    return out

