def sessionize(events, timeout, max_len):
    per_user = {}
    for ev in events:
        user, ts = ev[0], ev[1]
        is_logout = len(ev) > 2 and ev[2] == "logout"
        per_user.setdefault(user, []).append((ts, is_logout))
    out = []
    for user, evs in per_user.items():
        evs.sort()
        cur = None
        closed = False
        for ts, is_logout in evs:
            if cur is None or closed or ts - cur[2] > timeout or ts - cur[1] > max_len:
                if cur is not None:
                    out.append(tuple(cur))
                cur = [user, ts, ts, 0]
            cur[2] = ts
            cur[3] += 1
            closed = is_logout
        if cur is not None:
            out.append(tuple(cur))
    out.sort(key=lambda s: (s[1], s[0]))
    return out

