from functools import lru_cache


def make_change(amount, drawer):
    vals = sorted(drawer, reverse=True)
    avail = [max(0, drawer[v] - 1) for v in vals]

    @lru_cache(maxsize=None)
    def solve(i, rem):
        if i == len(vals):
            return (0, ()) if rem == 0 else None
        best = None
        v = vals[i]
        for c in range(min(avail[i], rem // v), -1, -1):
            sub = solve(i + 1, rem - c * v)
            if sub is None:
                continue
            cand = (c + sub[0], (c,) + sub[1])
            if best is None or cand[0] < best[0] or (cand[0] == best[0] and cand[1] > best[1]):
                best = cand
        return best

    res = solve(0, amount)
    if res is None:
        return None
    return {v: c for v, c in zip(vals, res[1]) if c}

