import heapq


def best_route(edges, start, goal, max_edges=None):
    adj = {}
    nodes = {start, goal}
    for e in edges:
        a, b, cost = e[0], e[1], e[2]
        nodes.update((a, b))
        adj.setdefault(a, []).append((b, cost))
        if not (len(e) > 3 and e[3] == "oneway"):
            adj.setdefault(b, []).append((a, cost))
    limit = len(nodes) - 1
    if max_edges is not None:
        limit = min(limit, max_edges)
    heap = [(0, 0, [start])]
    seen = set()
    while heap:
        cost, hops, path = heapq.heappop(heap)
        node = path[-1]
        if node == goal:
            return (cost, path)
        if (node, hops) in seen:
            continue
        seen.add((node, hops))
        if hops >= limit:
            continue
        for nxt, c in adj.get(node, []):
            heapq.heappush(heap, (cost + c, hops + 1, path + [nxt]))
    return None

