        limit = min(limit, max_edges)
    counter = 0
    heap = [(0, 0, 0, [start])]
    seen = set()
    while heap:
        cost, hops, _, path = heapq.heappop(heap)
        node = path[-1]
        if node == goal:
            return (cost, path)
        if (node, hops) in seen:
            continue
        seen.add((node, hops))
        if hops >= limit:
            continue
        for nxt, c in adj.get(node, []):
            counter += 1
            heapq.heappush(heap, (cost + c, hops + 1, counter, path + [nxt]))
    return None

