def test_basic_union_and_complement():
    busy = {'ann': [(60, 90), (30, 45)], 'bob': [(80, 120)]}
    assert common_free(busy, 0, 180, 0, 0) == [(0, 30), (45, 60), (120, 180)]

def test_nested_and_touching_intervals():
    assert common_free({'a': [(0, 100), (20, 30)], 'b': [(90, 110)]}, 0, 200, 0, 0) == [(110, 200)]
    assert common_free({'a': [(60, 90)], 'b': [(90, 120)]}, 0, 150, 1, 0) == [(0, 60), (120, 150)]

def test_clipping_and_people_without_meetings():
    assert common_free({'a': [(-50, 30), (250, 400)], 'b': []}, 0, 300, 0, 0) == [(30, 250)]
    assert common_free({}, 0, 300, 0, 0) == [(0, 300)]

def test_min_len_is_inclusive():
    assert common_free({'a': [(10, 20), (50, 60)]}, 0, 100, 30, 0) == [(20, 50), (60, 100)]

def test_buffer_on_both_sides():
    busy = {'a': [(60, 90)], 'b': [(130, 160)]}
    assert common_free(busy, 0, 300, 0, 10) == [(0, 50), (100, 120), (170, 300)]

def test_buffer_can_join_meetings():
    assert common_free({'a': [(60, 90), (105, 120)]}, 0, 200, 0, 10) == [(0, 50), (130, 200)]

def test_buffer_applied_before_clipping():
    busy = {'a': [(300, 400)], 'b': [(-40, -5)]}
    assert common_free(busy, 0, 300, 0, 15) == [(10, 285)]

def test_min_len_with_buffer():
    assert common_free({'a': [(30, 40)]}, 0, 100, 25, 5) == [(0, 25), (45, 100)]

